{
  "families": [
    {
      "budget_share": 0.5,
      "family": "pipelined",
      "ranges": [
        {
          "choices": [
            "trunc",
            "round"
          ],
          "high": 4,
          "low": 0,
          "param": "frac_guard"
        },
        {
          "choices": [
            "trunc",
